132	func newStartRestoredAgentConfirm(startAgent *bool, checkpointID string) *huh.Confirm {
133		description := "Entire restored the checkpoint session log. Choose No to print the resume command instead."
134		if checkpointID != "" {
135			description = fmt.Sprintf("Entire restored checkpoint %s. Choose No to print the resume command instead.", checkpointID)
136		}
137		return huh.NewConfirm().
138			Title("Start the agent now?").
139			Description(description).
140			Affirmative("Yes").
141			Negative("No").
142			Value(startAgent)
143	}
